-- 100+ Conversation Topics for English Learning Platform
-- Comprehensive coverage of all categories

INSERT INTO conversation_topics (title, category, difficulty_level, description, content, vocabulary) VALUES

-- MORALS & ETHICS (10 topics)
('The Importance of Honesty', 'Morals', 'Beginner', 'Discussing honesty in daily life', 'Honesty is one of the most important values in life. When we are honest, we build trust with others. People who are honest are respected in their communities. Being dishonest can damage relationships and reputation. It is better to tell the truth, even when it is difficult. Honesty creates a foundation for strong friendships and successful careers.', ARRAY['honesty', 'trust', 'reputation', 'relationships', 'values']),

('Integrity in the Workplace', 'Morals', 'Intermediate', 'Professional ethics and integrity', 'Workplace integrity means doing the right thing even when no one is watching. It involves being truthful in reporting, respecting confidential information, and treating colleagues fairly. Employees with integrity contribute to a positive work environment. Companies value workers who demonstrate ethical behavior. Maintaining professional standards builds long-term career success.', ARRAY['integrity', 'ethics', 'professional', 'accountability', 'transparency']),

('The Value of Compassion', 'Morals', 'Beginner', 'Understanding and practicing compassion', 'Compassion is the ability to understand and care about others'' suffering. When we show compassion, we make the world a better place. Simple acts of kindness can have a big impact on someone''s day. Compassionate people help create stronger communities. Teaching children compassion helps them become caring adults.', ARRAY['compassion', 'kindness', 'empathy', 'caring', 'understanding']),

('Fairness and Justice', 'Morals', 'Intermediate', 'Discussing concepts of fairness in society', 'Fairness means treating everyone equally and without bias. Justice systems aim to ensure fair treatment for all citizens. However, achieving true fairness can be challenging. Social inequality affects access to opportunities. We must work together to create a more just society where everyone has equal chances to succeed.', ARRAY['fairness', 'justice', 'equality', 'bias', 'inequality']),

('Responsibility and Accountability', 'Morals', 'Advanced', 'Personal and social responsibility', 'Taking responsibility for our actions is a sign of maturity. Accountability means accepting consequences, whether positive or negative. In leadership positions, accountability becomes even more critical. Organizations thrive when individuals own their mistakes and learn from them. A culture of responsibility drives innovation and continuous improvement.', ARRAY['responsibility', 'accountability', 'consequences', 'maturity', 'leadership']),

('The Ethics of Technology', 'Morals', 'Advanced', 'Moral implications of technological advancement', 'As technology advances, new ethical questions emerge. Privacy concerns arise with data collection. Artificial intelligence raises questions about decision-making authority. Social media platforms face challenges regarding content moderation. Society must balance innovation with ethical considerations. Tech companies have a responsibility to consider the moral impact of their products.', ARRAY['ethics', 'technology', 'privacy', 'artificial intelligence', 'innovation']),

('Forgiveness and Redemption', 'Morals', 'Intermediate', 'The power of forgiveness in relationships', 'Forgiveness is a powerful tool for healing relationships. Holding grudges can be emotionally exhausting. When we forgive, we free ourselves from negative emotions. Everyone makes mistakes and deserves a second chance. Redemption is possible when people genuinely change their behavior. Learning to forgive is essential for personal growth.', ARRAY['forgiveness', 'redemption', 'healing', 'grudges', 'second chance']),

('Courage and Moral Strength', 'Morals', 'Intermediate', 'Standing up for what is right', 'Moral courage means standing up for your beliefs, even when it is difficult. Speaking out against injustice requires bravery. Whistleblowers demonstrate courage by exposing wrongdoing. It takes strength to resist peer pressure and do the right thing. History honors those who showed moral courage during challenging times.', ARRAY['courage', 'bravery', 'justice', 'whistleblower', 'integrity']),

('Gratitude and Appreciation', 'Morals', 'Beginner', 'Practicing gratitude in daily life', 'Gratitude is appreciating what we have rather than focusing on what we lack. Expressing thanks strengthens relationships. Grateful people tend to be happier and more satisfied with life. Keeping a gratitude journal can improve mental health. Teaching children to be grateful helps them become more positive adults.', ARRAY['gratitude', 'appreciation', 'thankful', 'contentment', 'positive']),

('Humility and Modesty', 'Morals', 'Intermediate', 'The importance of staying humble', 'Humility involves recognizing our limitations and valuing others. Modest people do not boast about their achievements. Being humble allows us to learn from everyone we meet. Arrogance can alienate others and limit personal growth. Great leaders often demonstrate humility despite their accomplishments.', ARRAY['humility', 'modesty', 'humble', 'arrogance', 'achievement']),

-- CRIME & LAW (10 topics)
('Understanding Cybercrime', 'Crime', 'Advanced', 'Digital crimes in the modern age', 'Cybercrime has become one of the fastest-growing criminal activities. Hackers steal personal information, financial data, and corporate secrets. Phishing emails trick people into revealing passwords. Ransomware attacks can paralyze entire organizations. Law enforcement agencies struggle to keep pace with evolving cyber threats. Individuals must protect themselves with strong passwords and security awareness.', ARRAY['cybercrime', 'hacking', 'phishing', 'ransomware', 'security']),

('The Criminal Justice System', 'Crime', 'Advanced', 'How the justice system works', 'The criminal justice system includes law enforcement, courts, and corrections. Police investigate crimes and arrest suspects. Prosecutors present evidence in court. Defense attorneys protect the rights of the accused. Judges ensure fair trials. The jury decides guilt or innocence. Rehabilitation programs aim to reduce recidivism rates.', ARRAY['justice system', 'prosecution', 'defense', 'trial', 'rehabilitation']),

('White Collar Crime', 'Crime', 'Advanced', 'Financial and corporate crimes', 'White collar crimes are non-violent offenses committed for financial gain. Embezzlement involves stealing money from employers. Insider trading uses confidential information for stock profits. Tax evasion deprives governments of revenue. Ponzi schemes defraud investors. These crimes can cause massive economic damage and destroy public trust.', ARRAY['embezzlement', 'fraud', 'insider trading', 'tax evasion', 'corruption']),

('Juvenile Delinquency', 'Crime', 'Intermediate', 'Youth crime and rehabilitation', 'Juvenile delinquency refers to criminal behavior by minors. Many factors contribute to youth crime, including poverty, family problems, and peer pressure. The juvenile justice system focuses more on rehabilitation than punishment. Early intervention programs can prevent young people from becoming career criminals. Society must address root causes to reduce juvenile crime.', ARRAY['juvenile', 'delinquency', 'rehabilitation', 'intervention', 'prevention']),

('Drug Trafficking and Enforcement', 'Crime', 'Advanced', 'The war on drugs', 'Drug trafficking is a global criminal enterprise worth billions. Cartels use violence to control territory and supply chains. Law enforcement agencies work across borders to disrupt drug networks. Addiction drives demand for illegal substances. Some argue for decriminalization and treatment rather than incarceration. The debate continues over the most effective approach to drug policy.', ARRAY['trafficking', 'cartel', 'enforcement', 'addiction', 'decriminalization']),

('Identity Theft', 'Crime', 'Intermediate', 'Protecting personal information', 'Identity theft occurs when criminals steal personal information to commit fraud. Thieves may open credit accounts, file fake tax returns, or make purchases in your name. Victims can spend years repairing their credit and reputation. Shredding documents and monitoring credit reports helps prevent identity theft. Strong passwords and secure websites are essential for protection.', ARRAY['identity theft', 'fraud', 'personal information', 'credit', 'protection']),

('Organized Crime', 'Crime', 'Advanced', 'Criminal organizations and their operations', 'Organized crime groups engage in various illegal activities, from drug trafficking to human smuggling. The mafia, yakuza, and triads are well-known examples. These organizations operate like businesses with hierarchies and territories. Money laundering conceals criminal profits. International cooperation is necessary to combat transnational organized crime.', ARRAY['organized crime', 'mafia', 'trafficking', 'money laundering', 'cartel']),

('Domestic Violence', 'Crime', 'Intermediate', 'Understanding and preventing abuse', 'Domestic violence affects millions of families worldwide. It includes physical, emotional, and financial abuse. Victims often feel trapped and afraid to seek help. Support services provide shelter, counseling, and legal assistance. Education and awareness can help prevent abuse. Society must take domestic violence seriously and support survivors.', ARRAY['domestic violence', 'abuse', 'victim', 'support', 'prevention']),

('Forensic Science', 'Crime', 'Advanced', 'Using science to solve crimes', 'Forensic science applies scientific methods to criminal investigations. DNA analysis can identify suspects or exonerate the innocent. Fingerprinting remains a valuable identification tool. Ballistics experts analyze firearms evidence. Digital forensics recovers data from computers and phones. Advances in forensic technology continue to improve crime-solving capabilities.', ARRAY['forensic', 'DNA', 'fingerprint', 'ballistics', 'evidence']),

('Capital Punishment Debate', 'Crime', 'Advanced', 'The death penalty controversy', 'Capital punishment remains controversial worldwide. Supporters argue it deters crime and delivers justice. Opponents cite the risk of executing innocent people and question its morality. Some countries have abolished the death penalty. Others continue using it for serious crimes. The debate involves legal, ethical, and practical considerations.', ARRAY['capital punishment', 'death penalty', 'deterrent', 'justice', 'morality']),

-- HISTORY (10 topics)
('Ancient Civilizations', 'History', 'Intermediate', 'Early human societies and their achievements', 'Ancient civilizations laid the foundation for modern society. The Egyptians built pyramids and developed hieroglyphics. Mesopotamians invented writing and the wheel. The Greeks contributed philosophy and democracy. Romans created advanced engineering and legal systems. Chinese civilization developed paper, printing, and gunpowder. These achievements continue to influence us today.', ARRAY['civilization', 'pyramids', 'democracy', 'engineering', 'invention']),

('The Industrial Revolution', 'History', 'Advanced', 'Transformation of manufacturing and society', 'The Industrial Revolution began in Britain in the late 18th century. Steam engines powered factories and transportation. Mass production replaced handcrafted goods. Urbanization accelerated as people moved to cities for factory jobs. Living conditions were often poor for workers. Labor movements emerged to fight for better wages and conditions. This period fundamentally changed human society.', ARRAY['industrial revolution', 'factory', 'urbanization', 'labor', 'manufacturing']),

('World War II', 'History', 'Advanced', 'The deadliest conflict in human history', 'World War II lasted from 1939 to 1945 and involved most of the world''s nations. Nazi Germany invaded Poland, triggering the conflict. The Holocaust resulted in the genocide of six million Jews. The war saw unprecedented destruction and casualties. The atomic bombs dropped on Japan ended the conflict. The war reshaped global politics and created the United Nations.', ARRAY['world war', 'holocaust', 'genocide', 'atomic bomb', 'conflict']),

('The Renaissance', 'History', 'Intermediate', 'Cultural rebirth in Europe', 'The Renaissance was a period of cultural flowering in Europe from the 14th to 17th centuries. Artists like Leonardo da Vinci and Michelangelo created masterpieces. Scientific inquiry challenged traditional beliefs. Humanism emphasized individual potential. The printing press spread knowledge widely. This era marked the transition from medieval to modern thinking.', ARRAY['renaissance', 'humanism', 'masterpiece', 'printing press', 'cultural']),

('The Age of Exploration', 'History', 'Intermediate', 'Discovery and colonization', 'European explorers sailed across unknown seas seeking trade routes and new lands. Columbus reached the Americas in 1492. Magellan''s expedition circumnavigated the globe. These voyages led to colonization and cultural exchange. Indigenous populations suffered disease and exploitation. The Columbian Exchange transformed global agriculture and cuisine.', ARRAY['exploration', 'colonization', 'voyage', 'indigenous', 'trade']),

('The Cold War', 'History', 'Advanced', 'Ideological conflict between superpowers', 'The Cold War was a period of geopolitical tension between the United States and Soviet Union. Both sides engaged in an arms race and space race. Proxy wars occurred in Korea, Vietnam, and Afghanistan. The Berlin Wall symbolized the division between East and West. The Cuban Missile Crisis brought the world to the brink of nuclear war. The Cold War ended with the collapse of the Soviet Union in 1991.', ARRAY['cold war', 'superpower', 'arms race', 'proxy war', 'nuclear']),

('The French Revolution', 'History', 'Advanced', 'Overthrow of monarchy and birth of modern France', 'The French Revolution began in 1789 with the storming of the Bastille. Economic crisis and inequality fueled popular anger. The monarchy was overthrown and King Louis XVI executed. The Reign of Terror saw thousands guillotined. Napoleon Bonaparte eventually seized power. The revolution''s ideals of liberty, equality, and fraternity influenced movements worldwide.', ARRAY['revolution', 'monarchy', 'guillotine', 'terror', 'liberty']),

('Ancient Egypt', 'History', 'Beginner', 'The civilization of the Nile', 'Ancient Egypt was one of the world''s earliest civilizations. The Nile River provided water and fertile soil. Pharaohs ruled as god-kings. Egyptians built massive pyramids as tombs for their rulers. Hieroglyphics recorded their history and beliefs. They developed advanced mathematics and medicine. Egyptian civilization lasted over 3000 years.', ARRAY['egypt', 'pharaoh', 'pyramid', 'hieroglyphics', 'nile']),

('The Silk Road', 'History', 'Intermediate', 'Ancient trade routes connecting East and West', 'The Silk Road was a network of trade routes connecting China with the Mediterranean. Merchants transported silk, spices, and other luxury goods. Ideas, religions, and technologies also spread along these routes. Buddhism traveled from India to China via the Silk Road. The routes facilitated cultural exchange between civilizations. Marco Polo''s travels made the Silk Road famous in Europe.', ARRAY['silk road', 'trade route', 'merchant', 'spices', 'cultural exchange']),

('The Space Race', 'History', 'Intermediate', 'Competition to explore space', 'The Space Race was a Cold War competition between the USA and USSR. The Soviets launched Sputnik, the first artificial satellite, in 1957. Yuri Gagarin became the first human in space in 1961. America responded with the Apollo program. Neil Armstrong walked on the moon in 1969. The Space Race drove technological innovation and inspired generations.', ARRAY['space race', 'satellite', 'moon landing', 'astronaut', 'innovation']);

-- ARTIFICIAL INTELLIGENCE (10 topics)
INSERT INTO conversation_topics (title, category, difficulty_level, description, content, vocabulary) VALUES
('Introduction to AI', 'Artificial Intelligence', 'Beginner', 'Understanding artificial intelligence basics', 'Artificial Intelligence (AI) refers to machines that can perform tasks requiring human intelligence. AI systems can learn, reason, and solve problems. Examples include virtual assistants like Siri and Alexa. AI is used in many applications, from smartphone features to medical diagnosis. Machine learning allows computers to improve through experience. AI is transforming many industries.', ARRAY['artificial intelligence', 'machine learning', 'virtual assistant', 'algorithm', 'automation']),

('Machine Learning Fundamentals', 'Artificial Intelligence', 'Advanced', 'How machines learn from data', 'Machine learning is a subset of AI where systems learn from data without explicit programming. Supervised learning uses labeled data to train models. Unsupervised learning finds patterns in unlabeled data. Neural networks mimic the human brain''s structure. Deep learning uses multiple layers to process complex information. Training data quality significantly impacts model performance.', ARRAY['machine learning', 'neural network', 'deep learning', 'algorithm', 'training data']),

('AI Ethics and Bias', 'Artificial Intelligence', 'Advanced', 'Ethical considerations in AI development', 'AI systems can perpetuate or amplify existing biases in training data. Facial recognition may be less accurate for certain demographics. Algorithmic bias can affect hiring, lending, and criminal justice decisions. Transparency in AI decision-making is crucial. Developers must consider ethical implications. Regulation may be necessary to ensure fair AI systems.', ARRAY['ethics', 'bias', 'fairness', 'transparency', 'regulation']),

('Natural Language Processing', 'Artificial Intelligence', 'Advanced', 'Teaching computers to understand human language', 'Natural Language Processing (NLP) enables computers to understand and generate human language. Chatbots use NLP to communicate with users. Machine translation like Google Translate relies on NLP. Sentiment analysis determines emotional tone in text. Language models like GPT can generate human-like text. NLP applications continue to improve with more data and computing power.', ARRAY['natural language processing', 'chatbot', 'translation', 'sentiment analysis', 'language model']),

('Computer Vision', 'Artificial Intelligence', 'Advanced', 'Teaching machines to see and interpret images', 'Computer vision allows machines to interpret visual information. Facial recognition identifies people in photos. Autonomous vehicles use computer vision to navigate. Medical imaging analysis helps doctors detect diseases. Object detection identifies items in images. Convolutional neural networks excel at visual tasks.', ARRAY['computer vision', 'facial recognition', 'autonomous vehicle', 'object detection', 'neural network']),

('AI in Healthcare', 'Artificial Intelligence', 'Intermediate', 'Medical applications of artificial intelligence', 'AI is revolutionizing healthcare in many ways. Diagnostic algorithms can detect diseases from medical images. AI assists in drug discovery and development. Predictive models identify patients at risk for complications. Robotic surgery systems offer precision. AI chatbots provide medical information. However, human doctors remain essential for patient care.', ARRAY['healthcare', 'diagnosis', 'medical imaging', 'drug discovery', 'robotic surgery']),

('Autonomous Vehicles', 'Artificial Intelligence', 'Intermediate', 'Self-driving car technology', 'Autonomous vehicles use AI to navigate without human drivers. Sensors detect obstacles, traffic signs, and other vehicles. Machine learning processes sensor data to make driving decisions. Companies like Tesla and Waymo are developing this technology. Safety concerns and regulations must be addressed. Autonomous vehicles could reduce accidents and traffic congestion.', ARRAY['autonomous', 'self-driving', 'sensor', 'navigation', 'automation']),

('AI and Job Automation', 'Artificial Intelligence', 'Intermediate', 'Impact of AI on employment', 'AI automation is changing the job market. Repetitive tasks are increasingly performed by machines. Some jobs may disappear while new ones emerge. Workers need to develop skills that complement AI. Education and retraining programs become more important. Society must address the economic implications of automation.', ARRAY['automation', 'employment', 'skills', 'workforce', 'economy']),

('Robotics and AI', 'Artificial Intelligence', 'Intermediate', 'Intelligent machines in the physical world', 'Robotics combines mechanical engineering with AI. Industrial robots assemble products in factories. Service robots assist in hospitals and hotels. Agricultural robots help with farming tasks. Social robots interact with humans. Advances in AI make robots more capable and autonomous.', ARRAY['robotics', 'industrial robot', 'automation', 'autonomous', 'engineering']),

('The Future of AI', 'Artificial Intelligence', 'Advanced', 'Predictions and possibilities for artificial intelligence', 'The future of AI holds exciting possibilities and challenges. Artificial General Intelligence (AGI) could match human intelligence across all tasks. Quantum computing may dramatically increase AI capabilities. AI could help solve climate change and disease. Concerns exist about AI surpassing human control. International cooperation on AI safety is crucial.', ARRAY['future', 'artificial general intelligence', 'quantum computing', 'superintelligence', 'innovation']),

-- CRYPTOCURRENCY & BLOCKCHAIN (10 topics)
('Understanding Blockchain', 'Cryptocurrency', 'Intermediate', 'The technology behind cryptocurrencies', 'Blockchain is a distributed ledger technology that records transactions across multiple computers. Each block contains transaction data and is linked to previous blocks. This creates an immutable chain of records. Blockchain eliminates the need for central authorities. The technology enables cryptocurrencies but has many other applications. Smart contracts automate agreements on blockchain platforms.', ARRAY['blockchain', 'distributed ledger', 'immutable', 'decentralized', 'smart contract']),

('Bitcoin Basics', 'Cryptocurrency', 'Beginner', 'Introduction to the first cryptocurrency', 'Bitcoin is the first and most well-known cryptocurrency. Created by Satoshi Nakamoto in 2009, it operates without central banks. Bitcoin uses blockchain technology to record transactions. Mining involves solving complex mathematical problems to validate transactions. Bitcoin has a limited supply of 21 million coins. Its value fluctuates significantly.', ARRAY['bitcoin', 'cryptocurrency', 'mining', 'satoshi nakamoto', 'digital currency']),

('Ethereum and Smart Contracts', 'Cryptocurrency', 'Advanced', 'The programmable blockchain platform', 'Ethereum is a blockchain platform that supports smart contracts. These are self-executing contracts with terms written in code. Ethereum enables decentralized applications (DApps). Developers can create tokens and complex financial instruments. The Ethereum network uses gas fees for transactions. Ethereum 2.0 aims to improve scalability and energy efficiency.', ARRAY['ethereum', 'smart contract', 'decentralized application', 'gas fee', 'scalability']),

('Cryptocurrency Trading', 'Cryptocurrency', 'Intermediate', 'Buying and selling digital assets', 'Cryptocurrency trading occurs on exchanges like Coinbase and Binance. Traders buy low and sell high to make profits. Technical analysis helps predict price movements. Day trading requires constant monitoring. Long-term holding, or HODLing, is another strategy. Trading carries significant risks due to volatility.', ARRAY['trading', 'exchange', 'volatility', 'hodl', 'technical analysis']),

('DeFi - Decentralized Finance', 'Cryptocurrency', 'Advanced', 'Financial services without intermediaries', 'Decentralized Finance (DeFi) provides financial services using blockchain technology. Users can lend, borrow, and earn interest without banks. Liquidity pools enable decentralized exchanges. Yield farming offers high returns but carries risks. DeFi eliminates intermediaries but requires technical knowledge. Smart contract vulnerabilities pose security concerns.', ARRAY['defi', 'decentralized finance', 'liquidity pool', 'yield farming', 'lending']),

('NFTs - Non-Fungible Tokens', 'Cryptocurrency', 'Intermediate', 'Unique digital assets', 'Non-Fungible Tokens (NFTs) represent ownership of unique digital items. Artists sell digital art as NFTs. NFTs can represent music, videos, or virtual real estate. Each NFT has a unique identifier on the blockchain. Some NFTs sell for millions of dollars. Critics question their long-term value and environmental impact.', ARRAY['nft', 'non-fungible token', 'digital art', 'collectible', 'ownership']),

('Cryptocurrency Mining', 'Cryptocurrency', 'Advanced', 'Creating new coins through computation', 'Cryptocurrency mining validates transactions and creates new coins. Miners use powerful computers to solve complex mathematical problems. Proof of Work requires significant energy consumption. Mining pools combine resources to increase chances of success. Some cryptocurrencies are switching to Proof of Stake to reduce energy use.', ARRAY['mining', 'proof of work', 'proof of stake', 'hash rate', 'validation']),

('Crypto Security', 'Cryptocurrency', 'Intermediate', 'Protecting digital assets', 'Cryptocurrency security is crucial for protecting investments. Hardware wallets store private keys offline. Two-factor authentication adds extra protection. Phishing scams target crypto users. Exchange hacks have resulted in billions in losses. Users must practice good security hygiene to protect their assets.', ARRAY['security', 'wallet', 'private key', 'phishing', 'authentication']),

('Regulation and Legal Issues', 'Cryptocurrency', 'Advanced', 'Government oversight of cryptocurrencies', 'Cryptocurrency regulation varies by country. Some nations embrace crypto while others ban it. Tax authorities require reporting of crypto gains. Anti-money laundering laws apply to exchanges. Central banks are developing their own digital currencies. Regulation aims to protect consumers while allowing innovation.', ARRAY['regulation', 'legal', 'taxation', 'compliance', 'central bank digital currency']),

('The Future of Money', 'Cryptocurrency', 'Advanced', 'How digital currencies may transform finance', 'Cryptocurrencies could fundamentally change the financial system. Digital currencies enable fast, borderless transactions. Central banks are exploring digital versions of fiat currencies. Blockchain technology may improve financial transparency. Challenges include scalability, regulation, and adoption. The future financial system may blend traditional and crypto elements.', ARRAY['digital currency', 'financial system', 'innovation', 'adoption', 'transformation']),

-- ENVIRONMENTAL TOPICS (10 topics)
('Climate Change', 'Environment', 'Intermediate', 'Understanding global warming', 'Climate change refers to long-term shifts in global temperatures and weather patterns. Human activities, especially burning fossil fuels, are the primary cause. Rising temperatures cause ice caps to melt and sea levels to rise. Extreme weather events are becoming more frequent. Reducing carbon emissions is essential to slow climate change. Renewable energy sources offer solutions.', ARRAY['climate change', 'global warming', 'carbon emissions', 'renewable energy', 'sustainability']),

('Deforestation', 'Environment', 'Intermediate', 'Loss of forests and its impact', 'Deforestation is the permanent removal of forests. Logging for timber and clearing land for agriculture are main causes. Forests absorb carbon dioxide and produce oxygen. They provide habitat for countless species. Deforestation contributes to climate change and biodiversity loss. Sustainable forestry practices can help preserve forests.', ARRAY['deforestation', 'logging', 'habitat', 'biodiversity', 'conservation']),

('Ocean Pollution', 'Environment', 'Intermediate', 'Protecting marine ecosystems', 'Ocean pollution threatens marine life and ecosystems. Plastic waste forms massive garbage patches in oceans. Chemical runoff from agriculture harms marine organisms. Oil spills devastate coastal areas. Overfishing depletes fish populations. Reducing plastic use and improving waste management are necessary steps.', ARRAY['pollution', 'plastic', 'marine life', 'ecosystem', 'conservation']),

('Renewable Energy', 'Environment', 'Intermediate', 'Clean energy alternatives', 'Renewable energy comes from sources that naturally replenish. Solar panels convert sunlight into electricity. Wind turbines harness wind power. Hydroelectric dams generate power from flowing water. Geothermal energy uses heat from the earth. Renewable energy reduces dependence on fossil fuels and decreases pollution.', ARRAY['renewable energy', 'solar power', 'wind energy', 'hydroelectric', 'clean energy']),

('Recycling and Waste Management', 'Environment', 'Beginner', 'Reducing environmental impact through recycling', 'Recycling converts waste materials into new products. It reduces landfill waste and conserves natural resources. Paper, plastic, glass, and metal can be recycled. Composting organic waste creates nutrient-rich soil. Proper waste sorting improves recycling efficiency. Reducing consumption is even better than recycling.', ARRAY['recycling', 'waste management', 'composting', 'conservation', 'sustainability']),

('Air Pollution', 'Environment', 'Intermediate', 'Threats to air quality', 'Air pollution consists of harmful substances in the atmosphere. Vehicle emissions and industrial processes are major sources. Polluted air causes respiratory diseases and other health problems. Smog reduces visibility in cities. Particulate matter penetrates deep into lungs. Clean air regulations and electric vehicles can improve air quality.', ARRAY['air pollution', 'emissions', 'smog', 'particulate matter', 'air quality']),

('Endangered Species', 'Environment', 'Intermediate', 'Protecting wildlife from extinction', 'Many species face extinction due to human activities. Habitat loss is the primary threat. Poaching endangers elephants, rhinos, and tigers. Climate change disrupts ecosystems. Conservation programs work to protect endangered species. Zoos participate in breeding programs. International cooperation is necessary for wildlife protection.', ARRAY['endangered species', 'extinction', 'habitat loss', 'conservation', 'wildlife']),

('Sustainable Agriculture', 'Environment', 'Advanced', 'Farming practices for the future', 'Sustainable agriculture meets current food needs without compromising future generations. Organic farming avoids synthetic pesticides and fertilizers. Crop rotation maintains soil health. Precision agriculture uses technology to optimize resource use. Vertical farming produces food in urban areas. Sustainable practices protect the environment while ensuring food security.', ARRAY['sustainable agriculture', 'organic farming', 'crop rotation', 'food security', 'precision agriculture']),

('Water Conservation', 'Environment', 'Beginner', 'Preserving precious water resources', 'Water is essential for life but supplies are limited. Many regions face water scarcity. Agriculture consumes most freshwater. Simple actions like fixing leaks and taking shorter showers help. Drip irrigation reduces water waste in farming. Desalination converts seawater to freshwater but requires significant energy.', ARRAY['water conservation', 'scarcity', 'freshwater', 'irrigation', 'desalination']),

('Green Buildings', 'Environment', 'Advanced', 'Environmentally friendly construction', 'Green buildings minimize environmental impact and maximize efficiency. Energy-efficient design reduces heating and cooling costs. Solar panels and green roofs are common features. Water-saving fixtures conserve resources. Sustainable materials reduce environmental footprint. LEED certification recognizes environmentally responsible buildings.', ARRAY['green building', 'energy efficiency', 'sustainable design', 'leed certification', 'solar panels']),

-- TECHNOLOGY (10 topics)
('5G Technology', 'Technology', 'Intermediate', 'The next generation of mobile networks', '5G is the fifth generation of cellular network technology. It offers much faster speeds than 4G. Lower latency enables real-time applications. 5G supports more connected devices simultaneously. It will enable autonomous vehicles and smart cities. Implementation requires significant infrastructure investment.', ARRAY['5g', 'network', 'latency', 'bandwidth', 'connectivity']),

('Internet of Things', 'Technology', 'Intermediate', 'Connected devices in everyday life', 'The Internet of Things (IoT) connects everyday devices to the internet. Smart home devices can be controlled remotely. Wearable fitness trackers monitor health. Industrial IoT improves manufacturing efficiency. Security concerns exist with so many connected devices. IoT generates massive amounts of data for analysis.', ARRAY['iot', 'smart device', 'connectivity', 'sensors', 'automation']),

('Cloud Computing', 'Technology', 'Intermediate', 'Computing resources delivered over the internet', 'Cloud computing provides on-demand access to computing resources. Users can store data and run applications remotely. Services scale easily based on demand. Cloud providers like AWS, Azure, and Google Cloud dominate the market. Cloud computing reduces infrastructure costs. Data security and privacy are important considerations.', ARRAY['cloud computing', 'infrastructure', 'scalability', 'data storage', 'service provider']),

('Cybersecurity', 'Technology', 'Advanced', 'Protecting digital systems and data', 'Cybersecurity protects computer systems and networks from attack. Hackers use various techniques to breach systems. Firewalls and antivirus software provide basic protection. Encryption secures sensitive data. Multi-factor authentication adds security layers. Regular security updates patch vulnerabilities. Organizations must train employees in security best practices.', ARRAY['cybersecurity', 'hacking', 'encryption', 'firewall', 'vulnerability']),

('Quantum Computing', 'Technology', 'Advanced', 'The future of computation', 'Quantum computers use quantum mechanics to process information. They can solve certain problems much faster than classical computers. Qubits exist in multiple states simultaneously. Quantum computers could break current encryption methods. They may revolutionize drug discovery and materials science. Practical quantum computers remain years away from widespread use.', ARRAY['quantum computing', 'qubit', 'superposition', 'algorithm', 'computation']),

('Virtual Reality', 'Technology', 'Intermediate', 'Immersive digital experiences', 'Virtual Reality (VR) creates immersive digital environments. Users wear headsets to enter virtual worlds. VR has applications in gaming, education, and training. Medical students practice procedures in VR. Architects visualize buildings before construction. VR technology continues to improve and become more affordable.', ARRAY['virtual reality', 'vr headset', 'immersive', 'simulation', 'gaming']),

('Augmented Reality', 'Technology', 'Intermediate', 'Enhancing the real world with digital information', 'Augmented Reality (AR) overlays digital information on the real world. Pokemon Go popularized AR gaming. AR apps help with navigation and shopping. IKEA''s AR app shows how furniture looks in your home. Industrial workers use AR for maintenance guidance. AR glasses may become common in the future.', ARRAY['augmented reality', 'overlay', 'ar glasses', 'mixed reality', 'application']),

('3D Printing', 'Technology', 'Intermediate', 'Additive manufacturing technology', '3D printing creates objects layer by layer from digital designs. It enables rapid prototyping and customization. Medical applications include printing prosthetics and organs. Construction companies print building components. 3D printed food is being developed. The technology democratizes manufacturing.', ARRAY['3d printing', 'additive manufacturing', 'prototyping', 'customization', 'fabrication']),

('Biotechnology', 'Technology', 'Advanced', 'Using biology for technological advancement', 'Biotechnology applies biological processes to create products. Genetic engineering modifies organisms for desired traits. CRISPR allows precise gene editing. Synthetic biology creates new biological systems. Biofuels offer renewable energy alternatives. Ethical concerns surround genetic modification.', ARRAY['biotechnology', 'genetic engineering', 'crispr', 'synthetic biology', 'gene editing']),

('Smart Cities', 'Technology', 'Advanced', 'Using technology to improve urban life', 'Smart cities use technology to improve efficiency and quality of life. Sensors monitor traffic, air quality, and utilities. Data analytics optimize city services. Smart grids manage energy distribution. Connected infrastructure enables autonomous vehicles. Privacy concerns must be addressed.', ARRAY['smart city', 'urban planning', 'infrastructure', 'data analytics', 'efficiency']);

-- HEALTH & MEDICINE (10 topics)
INSERT INTO conversation_topics (title, category, difficulty_level, description, content, vocabulary) VALUES
('Mental Health Awareness', 'Health', 'Intermediate', 'Understanding and supporting mental wellness', 'Mental health is as important as physical health. Depression and anxiety affect millions worldwide. Therapy and counseling provide professional support. Stigma prevents many from seeking help. Exercise, sleep, and social connections improve mental wellness. Mental health days from work are becoming more accepted. Society must prioritize mental health resources.', ARRAY['mental health', 'depression', 'anxiety', 'therapy', 'wellness']),

('Nutrition and Diet', 'Health', 'Beginner', 'Eating for health and wellness', 'Proper nutrition is essential for good health. A balanced diet includes fruits, vegetables, proteins, and whole grains. Processed foods often contain excess sugar and salt. Drinking water helps maintain bodily functions. Reading nutrition labels helps make informed choices. Dietary needs vary by age, activity level, and health conditions.', ARRAY['nutrition', 'diet', 'balanced diet', 'vitamins', 'minerals']),

('Exercise and Fitness', 'Health', 'Beginner', 'The importance of physical activity', 'Regular exercise provides numerous health benefits. Cardiovascular exercise strengthens the heart. Strength training builds muscle and bone density. Exercise improves mood and reduces stress. Even moderate activity like walking makes a difference. Finding enjoyable activities increases consistency. Physical activity should be adapted to individual abilities.', ARRAY['exercise', 'fitness', 'cardiovascular', 'strength training', 'physical activity']),

('Vaccines and Immunization', 'Health', 'Intermediate', 'Preventing disease through vaccination', 'Vaccines protect against infectious diseases. They work by training the immune system. Childhood vaccinations prevent measles, polio, and other diseases. Flu shots reduce seasonal illness. Vaccine development requires extensive testing. Herd immunity protects vulnerable populations. Misinformation about vaccines poses public health risks.', ARRAY['vaccine', 'immunization', 'immune system', 'herd immunity', 'prevention']),

('Sleep and Health', 'Health', 'Beginner', 'The importance of quality sleep', 'Sleep is crucial for physical and mental health. Adults need 7-9 hours per night. Poor sleep affects concentration and mood. Sleep deprivation increases disease risk. Good sleep hygiene includes regular schedules and comfortable environments. Limiting screen time before bed improves sleep quality. Sleep disorders like insomnia require professional treatment.', ARRAY['sleep', 'insomnia', 'sleep hygiene', 'rest', 'circadian rhythm']),

('Telemedicine', 'Health', 'Intermediate', 'Healthcare via technology', 'Telemedicine provides medical care remotely using technology. Video consultations allow doctors to diagnose and treat patients. It improves access to healthcare in rural areas. Telemedicine expanded rapidly during the COVID-19 pandemic. It reduces travel time and costs. However, some conditions require in-person examination.', ARRAY['telemedicine', 'remote healthcare', 'consultation', 'digital health', 'accessibility']),

('Antibiotics and Resistance', 'Health', 'Advanced', 'The challenge of drug-resistant bacteria', 'Antibiotics kill bacteria that cause infections. Overuse has led to antibiotic resistance. Resistant bacteria are harder to treat. Taking antibiotics as prescribed is essential. Agriculture''s use of antibiotics contributes to resistance. New antibiotics are urgently needed. Responsible use helps preserve antibiotic effectiveness.', ARRAY['antibiotic', 'resistance', 'bacteria', 'infection', 'medication']),

('Cancer Treatment Advances', 'Health', 'Advanced', 'Modern approaches to fighting cancer', 'Cancer treatment has advanced significantly. Surgery removes tumors. Chemotherapy uses drugs to kill cancer cells. Radiation therapy targets tumors precisely. Immunotherapy harnesses the immune system. Targeted therapies attack specific cancer characteristics. Early detection improves survival rates. Research continues to develop better treatments.', ARRAY['cancer', 'chemotherapy', 'immunotherapy', 'treatment', 'oncology']),

('Public Health', 'Health', 'Advanced', 'Protecting community health', 'Public health focuses on preventing disease and promoting wellness in populations. Sanitation and clean water prevent many illnesses. Health education promotes healthy behaviors. Surveillance systems track disease outbreaks. Public health campaigns encourage vaccination and healthy lifestyles. Addressing social determinants improves health equity.', ARRAY['public health', 'prevention', 'epidemiology', 'health education', 'sanitation']),

('Alternative Medicine', 'Health', 'Intermediate', 'Complementary and traditional treatments', 'Alternative medicine includes treatments outside conventional medicine. Acupuncture, herbal remedies, and chiropractic are common forms. Some people combine alternative and conventional treatments. Scientific evidence varies for different therapies. Consultation with healthcare providers is important. Alternative medicine is popular in many cultures.', ARRAY['alternative medicine', 'acupuncture', 'herbal remedy', 'complementary therapy', 'holistic']),

-- LIFESTYLE & PERSONAL DEVELOPMENT (10 topics)
('Time Management', 'Lifestyle', 'Beginner', 'Making the most of your time', 'Effective time management increases productivity and reduces stress. Prioritizing tasks helps focus on what matters. To-do lists organize daily activities. The Pomodoro Technique uses timed work intervals. Eliminating distractions improves concentration. Saying no to non-essential commitments protects your time. Time management skills can be learned and improved.', ARRAY['time management', 'productivity', 'prioritization', 'organization', 'efficiency']),

('Work-Life Balance', 'Lifestyle', 'Intermediate', 'Balancing career and personal life', 'Work-life balance involves managing professional and personal responsibilities. Overwork leads to burnout and health problems. Setting boundaries protects personal time. Remote work can blur work-home boundaries. Employers increasingly recognize the importance of balance. Making time for family, hobbies, and rest is essential. Balance looks different for everyone.', ARRAY['work-life balance', 'burnout', 'boundaries', 'wellbeing', 'flexibility']),

('Building Confidence', 'Lifestyle', 'Beginner', 'Developing self-assurance', 'Confidence comes from believing in your abilities. Small successes build confidence over time. Positive self-talk combats negative thoughts. Preparing thoroughly reduces anxiety. Accepting failure as learning helps growth. Body language affects how others perceive you. Confidence can be developed through practice.', ARRAY['confidence', 'self-esteem', 'self-belief', 'assertiveness', 'growth']),

('Minimalism', 'Lifestyle', 'Intermediate', 'Living with less', 'Minimalism focuses on owning fewer possessions. It reduces clutter and stress. Minimalists keep only items that serve a purpose or bring joy. The lifestyle promotes intentional living. Minimalism can save money and time. It varies from person to person. The goal is finding what truly matters.', ARRAY['minimalism', 'simplicity', 'declutter', 'intentional living', 'essentialism']),

('Digital Detox', 'Lifestyle', 'Beginner', 'Reducing screen time and technology use', 'Digital detox involves temporarily disconnecting from technology. Constant connectivity can be exhausting. Social media comparison affects mental health. Taking breaks from screens improves sleep and focus. Designated phone-free times help maintain relationships. Notifications can be managed to reduce distractions. Balance is key to healthy technology use.', ARRAY['digital detox', 'screen time', 'technology', 'disconnect', 'mindfulness']),

('Personal Finance', 'Lifestyle', 'Intermediate', 'Managing money wisely', 'Personal finance involves managing income, expenses, and savings. Budgeting tracks where money goes. Emergency funds provide financial security. Investing grows wealth over time. Avoiding unnecessary debt is important. Understanding compound interest helps with long-term planning. Financial literacy should be taught early.', ARRAY['personal finance', 'budgeting', 'saving', 'investing', 'financial planning']),

('Habit Formation', 'Lifestyle', 'Intermediate', 'Building positive routines', 'Habits are behaviors performed automatically. Forming new habits requires consistency. Cue-routine-reward is the habit loop. Starting small increases success rates. Tracking progress provides motivation. Replacing bad habits with good ones is effective. Environment design supports habit formation. Change takes time and patience.', ARRAY['habit', 'routine', 'consistency', 'behavior change', 'discipline']),

('Stress Management', 'Lifestyle', 'Beginner', 'Coping with life''s pressures', 'Stress is a natural response to challenges. Chronic stress harms physical and mental health. Exercise reduces stress hormones. Meditation and deep breathing calm the mind. Social support provides emotional relief. Identifying stress triggers helps manage them. Professional help is available for overwhelming stress.', ARRAY['stress management', 'coping strategies', 'relaxation', 'mindfulness', 'resilience']),

('Goal Setting', 'Lifestyle', 'Beginner', 'Achieving your dreams', 'Clear goals provide direction and motivation. SMART goals are Specific, Measurable, Achievable, Relevant, and Time-bound. Breaking large goals into steps makes them manageable. Writing goals down increases commitment. Regular review keeps goals on track. Celebrating progress maintains motivation. Flexibility allows adjusting goals as needed.', ARRAY['goal setting', 'smart goals', 'planning', 'achievement', 'motivation']),

('Cultural Intelligence', 'Lifestyle', 'Advanced', 'Understanding and respecting different cultures', 'Cultural intelligence is the ability to work effectively across cultures. It involves understanding different values and customs. Curiosity and openness facilitate learning. Active listening helps understand perspectives. Avoiding stereotypes shows respect. Cultural intelligence is increasingly important in global business. It can be developed through education and experience.', ARRAY['cultural intelligence', 'diversity', 'cross-cultural', 'respect', 'global mindset']),

-- IELTS PREPARATION (10 topics)
('IELTS Speaking Part 1', 'IELTS', 'Intermediate', 'Introducing yourself and familiar topics', 'IELTS Speaking Part 1 lasts 4-5 minutes. The examiner asks about familiar topics like your home, work, or hobbies. Answers should be 2-3 sentences. Use varied vocabulary and grammar. Speak naturally and clearly. Practice common Part 1 topics. Extend your answers with reasons and examples. Show your personality in responses.', ARRAY['ielts', 'speaking', 'introduction', 'interview', 'fluency']),

('IELTS Speaking Part 2', 'IELTS', 'Advanced', 'Long turn individual presentation', 'Part 2 requires speaking for 2 minutes on a topic. You get 1 minute to prepare and make notes. Topics often ask you to describe a person, place, or experience. Use all your preparation time. Structure your answer with introduction, main points, and conclusion. Practice speaking for exactly 2 minutes. Use descriptive language and details.', ARRAY['ielts', 'long turn', 'description', 'fluency', 'coherence']),

('IELTS Speaking Part 3', 'IELTS', 'Advanced', 'Discussion of abstract topics', 'Part 3 involves discussing abstract ideas related to Part 2. Questions explore broader social issues. Give developed answers with explanations. Use advanced vocabulary and complex sentences. Compare, contrast, and speculate. Express and justify opinions. Think critically about topics. Show ability to discuss ideas in depth.', ARRAY['ielts', 'discussion', 'abstract topics', 'critical thinking', 'argumentation']),

('IELTS Writing Task 1 Academic', 'IELTS', 'Advanced', 'Describing visual information', 'Task 1 requires describing graphs, charts, tables, or diagrams in 150+ words. Identify key features and trends. Use varied vocabulary for describing data. Compare and contrast information. Organize your response logically. Avoid giving opinions. Write in formal academic style. Spend 20 minutes on this task.', ARRAY['ielts', 'academic writing', 'data description', 'graphs', 'formal style']),

('IELTS Writing Task 2', 'IELTS', 'Advanced', 'Essay writing on common topics', 'Task 2 is an essay of 250+ words worth more marks. Topics cover education, technology, environment, etc. Plan your essay structure first. Introduction states your position. Body paragraphs develop arguments with examples. Conclusion summarizes without new information. Use formal academic language. Allocate 40 minutes for this task.', ARRAY['ielts', 'essay writing', 'argumentation', 'academic style', 'organization']),

('IELTS Reading Strategies', 'IELTS', 'Intermediate', 'Improving reading comprehension', 'IELTS Reading has three passages with 40 questions. Skim passages to understand main ideas. Scan for specific information. Pay attention to keywords. Question types include matching, true/false, and multiple choice. Time management is crucial. Practice reading academic texts. Improve vocabulary through reading widely.', ARRAY['ielts', 'reading comprehension', 'skimming', 'scanning', 'strategies']),

('IELTS Listening Tips', 'IELTS', 'Intermediate', 'Mastering the listening test', 'Listening has four sections with increasing difficulty. Listen for keywords and synonyms. Be ready before each section starts. Write answers during the recording. Check spelling and grammar. All answer types appear: multiple choice, completion, matching. Concentration is essential. Practice with various accents.', ARRAY['ielts', 'listening', 'comprehension', 'note-taking', 'concentration']),

('Vocabulary for IELTS', 'IELTS', 'Intermediate', 'Building academic vocabulary', 'Strong vocabulary improves all IELTS sections. Learn topic-specific vocabulary. Understand collocations and word families. Use synonyms to avoid repetition. Academic word lists are helpful. Context helps remember new words. Create vocabulary notebooks organized by topic. Review regularly for retention.', ARRAY['vocabulary', 'academic words', 'collocations', 'synonyms', 'word family']),

('Grammar for IELTS', 'IELTS', 'Advanced', 'Mastering complex grammatical structures', 'Grammatical range and accuracy affect your score. Use various sentence structures. Master complex sentences with clauses. Ensure subject-verb agreement. Use appropriate tenses. Conditional sentences show sophistication. Avoid common errors. Passive voice is useful in academic writing. Practice makes perfect.', ARRAY['grammar', 'sentence structure', 'tenses', 'complex sentences', 'accuracy']),

('IELTS Test Day Tips', 'IELTS', 'Beginner', 'Preparing for exam day', 'Arrive early at the test center. Bring required identification. Get good sleep before the exam. Eat a healthy breakfast. Stay calm and focused. Read all instructions carefully. Manage your time wisely. Answer all questions even if unsure. Check your work if time permits. Stay positive throughout.', ARRAY['test preparation', 'exam strategy', 'time management', 'confidence', 'performance']);
